import{_ as a,o as n,c as i,a6 as t}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"12 · Prompt 缓存：省钱省延迟最立竿见影的一招","description":"系统提示和工具定义每轮重发、重算，又贵又慢。Prompt 缓存让稳定的前缀被复用，cache-read 的价格常只有正常输入的十分之一。讲清缓存断点怎么放、滚动断点如何跟住增长的历史，以及那条“改一个字节、缓存全废”的字节稳定性红线。","frontmatter":{"title":"12 · Prompt 缓存：省钱省延迟最立竿见影的一招","description":"系统提示和工具定义每轮重发、重算，又贵又慢。Prompt 缓存让稳定的前缀被复用，cache-read 的价格常只有正常输入的十分之一。讲清缓存断点怎么放、滚动断点如何跟住增长的历史，以及那条“改一个字节、缓存全废”的字节稳定性红线。","source":"https://daiw.org/manual/llm-to-agent/prompt-caching"},"headers":[],"relativePath":"manual/agent/llm-to-agent/prompt-caching.md","filePath":"manual/agent/llm-to-agent/prompt-caching.md"}'),l={name:"manual/agent/llm-to-agent/prompt-caching.md"};function e(p,s,r,o,h,k){return n(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="_12-·-prompt-缓存-省钱省延迟最立竿见影的一招" tabindex="-1">12 · Prompt 缓存：省钱省延迟最立竿见影的一招 <a class="header-anchor" href="#_12-·-prompt-缓存-省钱省延迟最立竿见影的一招" aria-label="Permalink to &quot;12 · Prompt 缓存：省钱省延迟最立竿见影的一招&quot;">​</a></h1><blockquote><p>系统提示和工具定义每轮重发、重算，又贵又慢。Prompt 缓存让稳定的前缀被复用，cache-read 的价格常只有正常输入的十分之一。讲清缓存断点怎么放、滚动断点如何跟住增长的历史，以及那条“改一个字节、缓存全废”的字节稳定性红线。</p></blockquote><p><a href="/Front2Full/manual/agent/llm-to-agent/context-injection">上一篇</a>我们看清了上下文由哪些层拼成，也埋下了那条“静态放高处”的原则。这一篇，兑现它的价值——用 Prompt 缓存，把靠前那些稳定的部分从“每轮重算”变成“一次算、多轮复用”。这是整个 Agent 里<strong>投入产出比最高</strong>的一个优化。</p><h2 id="一、背景-你在为同一段文字反复付钱" tabindex="-1">一、背景：你在为同一段文字反复付钱 <a class="header-anchor" href="#一、背景-你在为同一段文字反复付钱" aria-label="Permalink to &quot;一、背景：你在为同一段文字反复付钱&quot;">​</a></h2><p>看清<a href="/Front2Full/manual/agent/llm-to-agent/context-injection">上一篇</a>那个分层后，一个浪费触目惊心：</p><ul><li><strong>系统提示</strong>几千 token(行为规范、工具指南)，每轮不变。</li><li><strong>工具定义</strong>几十个工具的 schema，又是几千 token，每轮不变。</li><li>可是<a href="/Front2Full/manual/agent/llm-to-agent/raw-llm-api">模型无状态</a>，<strong>每一轮你都得把这几千 token 原样重发</strong>，模型也<strong>每一轮都从头重新处理</strong>它们。</li></ul><p>一个几十轮的 Agent 会话，同一段系统提示被重新计算了几十遍。<strong>你在为完全相同的一段文字，反复付钱、反复等待。</strong> 这纯属浪费——它每轮都一模一样，凭什么要重算？</p><h2 id="二、解决方案-缓存稳定的前缀" tabindex="-1">二、解决方案：缓存稳定的前缀 <a class="header-anchor" href="#二、解决方案-缓存稳定的前缀" aria-label="Permalink to &quot;二、解决方案：缓存稳定的前缀&quot;">​</a></h2><p>Prompt 缓存的思路：<strong>让 API 把 prompt 的某个前缀缓存下来；下一个请求只要前缀一字不差，就直接复用缓存的计算结果，跳过重算。</strong></p><ul><li><strong>命中缓存的部分</strong>，按 <strong>cache-read</strong> 计价——通常只有正常输入 token 价格的<strong>约十分之一</strong>，而且延迟大幅降低(模型不用重读它)。</li><li>第一次建立缓存，有一点点额外的 <strong>cache-write</strong> 开销(略高于正常输入)，但后续每一轮都在赚回来。</li></ul><p>用法上，你在 prompt 里打若干<strong>缓存断点</strong>(cache breakpoint)，告诉 API “缓存到这里为止”：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.messages.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  model,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 系统提示以&quot;块&quot;形式给出,末尾打一个缓存断点</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  system: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;text&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, text: bigSystemPrompt, cache_control: { type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ephemeral&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 工具定义也很稳定,在最后一个工具上打断点,缓存整个工具区</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  tools: [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lastTool, cache_control: { type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ephemeral&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  messages,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>响应的 <code>usage</code> 会告诉你缓存命中情况：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  cache_creation_input_tokens</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 这次写入缓存的量(第一轮)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  cache_read_input_tokens</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ——下一轮——</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  cache_creation_input_tokens</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  cache_read_input_tokens</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 这次命中缓存的量(便宜十倍!)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  input_tokens</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">130</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 只有真正新增的部分按全价算</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="三、关键机制-前缀缓存-滚动断点" tabindex="-1">三、关键机制：前缀缓存 + 滚动断点 <a class="header-anchor" href="#三、关键机制-前缀缓存-滚动断点" aria-label="Permalink to &quot;三、关键机制：前缀缓存 + 滚动断点&quot;">​</a></h2><h3 id="缓存是-前缀-的-不是-任意片段-的" tabindex="-1">缓存是“前缀”的，不是“任意片段”的 <a class="header-anchor" href="#缓存是-前缀-的-不是-任意片段-的" aria-label="Permalink to &quot;缓存是“前缀”的，不是“任意片段”的&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>缓存匹配的是从 prompt <strong>最开头</strong>算起、一字不差的</strong>前缀**。** 这有两个硬含义：</p><ol><li>断点之<strong>前</strong>的所有内容必须完全稳定——所以稳定的东西(系统提示、工具)要放最前面(这就是<a href="/Front2Full/manual/agent/llm-to-agent/context-injection">上一篇</a>“静态放高处”的兑现)。</li><li>你不能只缓存“中间某段”。缓存永远是“从头到某个断点”的一整段。</li></ol></div><h3 id="滚动断点-让缓存跟住增长的历史" tabindex="-1">滚动断点：让缓存跟住增长的历史 <a class="header-anchor" href="#滚动断点-让缓存跟住增长的历史" aria-label="Permalink to &quot;滚动断点：让缓存跟住增长的历史&quot;">​</a></h3><p>系统提示和工具好办(它们不变)。但<strong>消息历史</strong>是一直增长的——难道历史部分就没法缓存了？</p><p>有办法：<strong>在历史里也放一个“滚动”的断点，让它随对话往前移。</strong> 关键洞察是——一轮结束后，<strong>本轮的历史会成为下一轮历史的稳定前缀</strong>。所以你把断点打在“当前历史的末尾附近”，下一轮这段历史没变，就整段命中缓存，只有最新增的一两条消息按全价算。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 N 轮:  [系统][工具][—— 历史 1..N ——|断点]  ← 缓存写入到这</span></span>
<span class="line"><span>第 N+1 轮:[系统][工具][—— 历史 1..N ——][新增 N+1|断点]</span></span>
<span class="line"><span>                       └─ 这段整个命中缓存 ─┘  └ 只有这点按全价</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>于是一个长会话里，<strong>绝大部分上下文每轮都在走 cache-read</strong>，只有最新的增量按全价。成本和延迟被压到极低。</p><h2 id="四、那条不容触碰的红线-字节稳定性" tabindex="-1">四、那条不容触碰的红线：字节稳定性 <a class="header-anchor" href="#四、那条不容触碰的红线-字节稳定性" aria-label="Permalink to &quot;四、那条不容触碰的红线：字节稳定性&quot;">​</a></h2><p>现在讲这一篇、也是整个上下文工程里<strong>最凶险</strong>的一个坑。缓存靠“字节级前缀匹配”，这意味着：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>断点之前的内容，哪怕只变了一个字节，从那一点往后的缓存</strong>全部作废**。** 这条红线，会以各种隐蔽的方式咬你：</p><ul><li><strong>在系统提示开头放了动态数据</strong>(精确到秒的时间戳、一个随机 ID)——每轮都变，缓存<strong>从头就废</strong>，你以为开了缓存，其实一次都没命中。</li><li><strong>顺手“规范化”了一条要复用的历史消息</strong>(把相对路径改成绝对路径、重新格式化了 JSON)——从那条消息往后，缓存全废。</li><li><strong>工具的顺序不稳定</strong>(每轮动态拼工具列表，顺序还会变)——工具区的缓存废掉。</li><li><strong>同一段内容，这轮用了紧凑 JSON、下轮用了带缩进的</strong>——字节不同，缓存不认。</li></ul></div><p>这条红线直接决定了一个贯穿代码的纪律，也解释了<a href="/Front2Full/manual/agent/llm-to-agent/context-injection">上一篇</a>那个“别原地改要复用的消息”的告诫：</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>凡是会流回下一轮 API 的消息，必须保持字节不变；要给观察者(UI、日志)加工过的版本，请</strong>拷贝一份<strong>去改，别动原件。</strong> 这就是为什么成熟 Agent 的代码里，处处能看到“克隆一份用于展示/序列化，原始消息原封不动送回 API”的写法——不是洁癖，是<strong>每一次原地修改，都可能是一次静默的缓存击穿</strong>，而缓存击穿在账单和延迟上都是实打实的损失，还极难排查(功能正常，就是莫名其妙又贵又慢)。</p></div><h2 id="五、和压缩的微妙关系" tabindex="-1">五、和压缩的微妙关系 <a class="header-anchor" href="#五、和压缩的微妙关系" aria-label="Permalink to &quot;五、和压缩的微妙关系&quot;">​</a></h2><p>缓存和<a href="/Front2Full/manual/agent/llm-to-agent/auto-compaction">下一篇的压缩</a>是一对需要小心协调的机制：</p><ul><li><strong>压缩会重写历史</strong>(把一大段老消息换成一段摘要)。这必然改变字节，所以<strong>压缩点之后的缓存会失效</strong>——压缩省了上下文，却付出了一次缓存重建的代价。</li><li>正因如此，精细的做法会尽量让压缩<strong>只动很老、本来也快过期的那部分缓存</strong>，而保住近期的热缓存；甚至有“按 <code>tool_use_id</code> 精确删除某几条工具结果、不碰其余字节”的技巧(<a href="/Front2Full/manual/agent/llm-to-agent/context-compaction">下下篇</a>会讲)，就是为了在减负的同时，尽量少破坏缓存。</li></ul><p><strong>“省”(缓存)和“减”(压缩)这两条路，在这里交汇并互相牵制</strong>——这也是上下文工程之所以难的原因：它不是几个独立技巧，而是一组互相拉扯、需要通盘权衡的约束。</p><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><p>Prompt 缓存是那种“投入极小、回报极大”的优化：给稳定前缀打几个断点，长会话的成本和延迟就能降一大截。但它有一条不容触碰的红线——<strong>字节稳定性</strong>：</p><ol><li>稳定的放前面(系统提示、工具)，动态的放后面。</li><li>在增长的历史里用滚动断点，让缓存跟住。</li><li><strong>凡是回流 API 的消息，一个字节都别原地改</strong>；要改就拷贝。</li></ol><p>缓存解决了“重复的部分别重算”。但它救不了另一半问题：当历史本身<strong>膨胀到装不下</strong>时，你不能光靠缓存，你得真的<strong>把它变小</strong>。下一篇<a href="/Front2Full/manual/agent/llm-to-agent/auto-compaction">自动压缩</a>，我们正面处理这头猛兽。</p><hr><p><strong>本篇对应代码</strong>：配套仓库给系统提示与工具定义加上缓存断点，并在 usage 里打印缓存命中(<code>src/agent.ts</code>)。<code>git checkout article-12</code>。</p>`,37)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
